import { router } from '../_core/trpc';
import { governedPublicProcedure as publicProcedure } from '../governance/trpc-enforcement';
import { z } from 'zod';

export const planesRouter = router({
  getControlPlaneOrgs: publicProcedure
    .input(z.object({
      limit: z.number().min(1).max(100).default(10),
      offset: z.number().min(0).default(0)
    }))
    .query(async ({ input }) => {
      try {
        // Mock org data
        const orgs = [
          {
            id: '1',
            name: 'Example Org',
            plan: 'professional' as const,
            createdAt: new Date(),
            settings: {
              maxApiKeys: 100,
              maxSurfaces: 50,
              maxArtifactsPerDay: 1000,
              retentionDays: 90,
              features: ['gates', 'experiments']
            }
          }
        ];

        return {
          success: true,
          data: orgs.slice(input.offset, input.offset + input.limit),
          error: null
        };
      } catch (error: unknown) {
        return {
          success: false,
          data: null,
          error: error.message
        };
      }
    }),

  getDataPlaneStats: publicProcedure
    .input(z.object({
      orgId: z.string()
    }))
    .query(async ({ input }) => {
      try {
        const stats = {
          pending: 12,
          processing: 3,
          completed: 1247,
          failed: 8,
          deadLetter: 0,
          avgProcessingTimeMs: 1250,
          throughputPerMinute: 45
        };

        return {
          success: true,
          data: stats,
          error: null
        };
      } catch (error: unknown) {
        return {
          success: false,
          data: null,
          error: error.message
        };
      }
    }),

  getAuditEntries: publicProcedure
    .input(z.object({
      orgId: z.string(),
      limit: z.number().min(1).max(50).default(20)
    }))
    .query(async ({ input }) => {
      try {
        const entries = [
          {
            id: '1',
            orgId: input.orgId,
            timestamp: new Date(),
            actor: 'system',
            action: 'gate.check',
            resource: 'surface',
            resourceId: 'surf_123',
            details: { status: 'passed' }
          }
        ];

        return {
          success: true,
          data: entries.slice(0, input.limit),
          error: null
        };
      } catch (error: unknown) {
        return {
          success: false,
          data: null,
          error: error.message
        };
      }
    })
});

